"""Zero-build Scheduling Management and Consumption Analytics browser shell."""
from __future__ import annotations


def operations_ui_html() -> str:
    return _HTML


_HTML = r'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RASAi · Operações SaaS</title><style>
:root{font-family:system-ui,sans-serif;color:#172033;background:#f5f7fa}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1380px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;align-items:center}.tabs{display:flex;gap:8px;margin:18px 0}.tabs button,.btn,button{border:1px solid #ccd3dd;background:white;border-radius:8px;padding:8px 11px;cursor:pointer}.btn.primary,.tabs button.active{background:#172033;color:white}.panel{display:none}.panel.active{display:block}.card{background:white;border:1px solid #e1e6ed;border-radius:12px;padding:16px;margin-bottom:14px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.grid label{display:grid;gap:5px;font-size:.8rem}.check{display:flex!important;align-items:center;gap:7px}.check input{width:auto}input,select,textarea{width:100%;padding:8px;border:1px solid #ccd3dd;border-radius:7px;background:white}.wide{grid-column:span 2}.full{grid-column:1/-1}.actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.table{overflow:auto}table{width:100%;border-collapse:collapse;font-size:.82rem}th,td{padding:9px;border-bottom:1px solid #edf0f4;text-align:left;vertical-align:top}th{background:#f8fafc}.muted{color:#667085}.error{color:#b42318}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:14px}.metric{background:white;border:1px solid #e1e6ed;border-radius:9px;padding:12px}.metric b{display:block;font-size:1.35rem}.hidden{display:none!important}.tag{padding:2px 6px;border:1px solid #d8dee8;border-radius:999px;font-size:.72rem;white-space:nowrap}.mono{font-family:ui-monospace,monospace;font-size:.76rem}.shiftbar{display:flex;gap:6px;flex-wrap:wrap}.detail{max-height:340px;overflow:auto}.inline-actions{display:flex;gap:5px;flex-wrap:wrap}.inline-actions button{padding:5px 7px;font-size:.75rem}@media(max-width:850px){.grid,.metrics{grid-template-columns:1fr}.wide,.full{grid-column:auto}}
</style></head><body><div class="wrap"><div class="top"><div><h1>Operações SaaS</h1><div class="muted">Scheduling Management e Consumption Analytics</div></div><a href="/app">Voltar ao RASAi</a></div><div id="msg"></div>
<div class="card grid"><label>Organização<select id="org"></select></label><label>Workspace<select id="ws"></select></label><label>Projeto<select id="project"></select></label><label>Property<select id="property"></select></label><label>Environment<select id="environment"></select></label></div>
<div class="tabs"><button class="active" data-tab="schedule">Agendamentos</button><button data-tab="usage">Consumo</button></div>
<section id="schedule" class="panel active"><div class="card"><h2 id="form-title">Novo agendamento</h2><input id="s-id" type="hidden"><div class="grid">
<label>Nome<input id="s-name" value="Auditoria recorrente"></label><label>Tipo<select id="s-type"><option>AUDIT</option><option>SEARCH_MONITOR</option><option>REPORT_REFRESH</option></select></label><label>Timezone IANA<input id="s-zone"></label><label>Overlap<select id="s-overlap"><option>SKIP</option><option>QUEUE</option></select></label>
<label>Horários locais<input id="s-times" value="08:00,18:00" placeholder="08:00,12:00,18:00"></label><label>Dias semana ISO 1-7<input id="s-weekdays" value="1,2,3,4,5" placeholder="1,2,3,4,5"></label><label>Dias do mês<input id="s-monthdays" placeholder="1,15,30"></label><label class="check">Último dia do mês <input id="s-lastday" type="checkbox"></label>
<label>Intervalo em minutos<input id="s-every" type="number" min="60" placeholder="ex.: 240"></label><label>Janela inicial<input id="s-start" value="00:00"></label><label>Janela final<input id="s-end" value="23:59"></label><label>Prioridade / tentativas<div style="display:flex;gap:6px"><input id="s-priority" type="number" min="0" max="1000" value="100"><input id="s-attempts" type="number" min="1" max="100" value="3"></div></label>
<div class="full"><span class="muted">Atalhos de janela:</span> <span class="shiftbar"><button data-shift="00:00,05:59">Madrugada</button><button data-shift="06:00,11:59">Manhã</button><button data-shift="12:00,17:59">Tarde</button><button data-shift="18:00,23:59">Noite</button></span></div>
<label class="wide" id="urls-label">URLs, uma por linha<textarea id="s-urls" rows="5" placeholder="/pagina-a&#10;/pagina-b"></textarea></label><label class="wide hidden" id="query-label">Query Registry ID<input id="s-query" placeholder="QRY-..."></label><label class="wide hidden" id="surface-label">Report surface<select id="s-surface"><option value="portfolio">portfolio</option></select></label>
<label class="full" id="audit-payload-label">Configuração AUDIT canônica (JSON, sem credenciais)<textarea id="s-audit-payload" rows="16" class="mono"></textarea><span class="muted">Os defaults são carregados do mesmo contrato usado pelo worker/CLI. Edite somente parâmetros de auditoria; chaves e tokens são rejeitados.</span></label>
</div><div class="actions"><button class="btn primary" id="save">Criar schedule</button><button class="btn hidden" id="cancel-edit">Cancelar edição</button><button class="btn" id="reload">Atualizar lista</button><button class="btn" id="reset-audit">Restaurar defaults AUDIT</button></div></div>
<div class="card"><h2>Schedules</h2><div id="schedules"></div></div><div class="card hidden" id="schedule-detail"><h2>Histórico / execuções</h2><div id="schedule-detail-body" class="detail"></div></div></section>
<section id="usage" class="panel"><div class="card"><h2>Consumption Analytics</h2><div class="grid"><label>Período<select id="u-period"><option value="TODAY">Hoje</option><option value="YESTERDAY">Ontem</option><option value="LAST_7_DAYS">Últimos 7 dias</option><option value="LAST_30_DAYS" selected>Últimos 30 dias</option><option value="CURRENT_MONTH">Mês atual</option><option value="PREVIOUS_MONTH">Mês anterior</option><option value="CUSTOM">Personalizado</option></select></label><label>Timezone IANA<input id="u-zone"></label><label class="custom-range hidden">Início ISO<input id="u-start" placeholder="2026-09-01T00:00:00-03:00"></label><label class="custom-range hidden">Fim ISO<input id="u-end" placeholder="2026-10-01T00:00:00-03:00"></label>
<label>Domínio<input id="u-domain"></label><label>URL<input id="u-url"></label><label>Usuário<input id="u-user" placeholder="USR-..."></label><label>Tipo de execução<select id="u-job"><option value="">Todos</option><option>AUDIT</option><option>SEARCH_MONITOR</option><option>REPORT_REFRESH</option></select></label><label>Provider<input id="u-provider"></label><label>Integração<input id="u-integration"></label><label>Operação<input id="u-operation"></label><label>Status<input id="u-status"></label><label>Modelo<input id="u-model"></label><label>Recurso<input id="u-resource" placeholder="AI, INTEGRATION, BROWSER..."></label><label class="wide">Agrupar por<input id="u-group" value="property,url,user,provider,category"></label></div><div class="actions"><button class="btn primary" id="usage-load">Consultar</button></div></div><div id="usage-metrics" class="metrics"></div><div class="card"><div id="usage-coverage" class="muted"></div><div id="usage-table"></div></div></section></div>
<script>
const $=x=>document.getElementById(x),state={schedules:[],auditDefaults:{}};const browserZone=()=>{try{return Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC'}catch{return'UTC'}};$('s-zone').value=browserZone();$('u-zone').value=browserZone();
const dev=()=>sessionStorage.getItem('rasai-dev-user')||'';function headers(extra={}){let h={...extra};if(dev())h['x-rasai-user-id']=dev();return h}async function api(path,opt={}){let r=await fetch(path,{...opt,headers:headers(opt.headers||{})});let b;try{b=await r.json()}catch{b={}}if(!r.ok)throw new Error(b.detail||('HTTP '+r.status));return b}function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function msg(v,e=false){$('msg').innerHTML=v?`<p class="${e?'error':''}">${esc(v)}</p>`:''}function opts(id,a,key,label){let el=$(id),old=el.value;el.innerHTML=a.map(x=>`<option value="${esc(x[key])}">${esc(label(x))}</option>`).join('');if(a.some(x=>x[key]===old))el.value=old;return el.value}function ints(v){return v.split(',').map(x=>x.trim()).filter(Boolean).map(Number)}function resetAuditPayload(){ $('s-audit-payload').value=JSON.stringify(state.auditDefaults||{},null,2)}
async function boot(){try{let [orgs,contract]=await Promise.all([api('/api/v1/organizations'),api('/api/v1/audit-job-options')]);state.orgs=orgs;state.auditDefaults=contract.defaults||{};resetAuditPayload();let o=opts('org',state.orgs,'organization_id',x=>x.name);if(!o)return;state.ws=await api(`/api/v1/organizations/${o}/workspaces`);await chooseWorkspace()}catch(e){msg(e.message,true)}}async function chooseWorkspace(){let w=opts('ws',state.ws,'workspace_id',x=>x.name);if(!w)return;state.projects=await api(`/api/v1/workspaces/${w}/projects`);await chooseProject()}async function chooseProject(){let p=opts('project',state.projects,'project_id',x=>x.name);if(!p)return;state.props=await api(`/api/v1/projects/${p}/properties`);await chooseProperty();await loadSchedules()}async function chooseProperty(){let p=opts('property',state.props,'property_id',x=>x.name+' · '+x.hostname);if(!p)return;state.envs=await api(`/api/v1/properties/${p}/environments`);opts('environment',state.envs,'environment_id',x=>x.name)}
function typeFields(){let t=$('s-type').value;$('urls-label').classList.toggle('hidden',t!=='AUDIT');$('audit-payload-label').classList.toggle('hidden',t!=='AUDIT');$('reset-audit').classList.toggle('hidden',t!=='AUDIT');$('query-label').classList.toggle('hidden',t!=='SEARCH_MONITOR');$('surface-label').classList.toggle('hidden',t!=='REPORT_REFRESH')}function recurrence(){let r={times:$('s-times').value.split(',').map(x=>x.trim()).filter(Boolean),weekdays:ints($('s-weekdays').value),month_days:ints($('s-monthdays').value),last_day:$('s-lastday').checked,window_start:$('s-start').value,window_end:$('s-end').value};if($('s-every').value)r.every_minutes=Number($('s-every').value);return r}function payload(){let t=$('s-type').value;if(t==='AUDIT'){let value;try{value=JSON.parse($('s-audit-payload').value||'{}')}catch{throw new Error('Configuração AUDIT deve ser JSON válido.')}if(!value||Array.isArray(value)||typeof value!=='object')throw new Error('Configuração AUDIT deve ser um objeto JSON.');return value}if(t==='SEARCH_MONITOR')return{query_id:$('s-query').value.trim()};return{surface:$('s-surface').value}}
function scheduleBody(){return{property_id:$('property').value,environment_id:$('environment').value,name:$('s-name').value,job_type:$('s-type').value,timezone:$('s-zone').value,overlap_policy:$('s-overlap').value,priority:Number($('s-priority').value),max_attempts:Number($('s-attempts').value),urls:$('s-type').value==='AUDIT'?$('s-urls').value.split(/\n/).map(x=>x.trim()).filter(Boolean):[],payload:payload(),recurrence:recurrence()}}
function resetForm(){ $('s-id').value='';$('form-title').textContent='Novo agendamento';$('save').textContent='Criar schedule';$('cancel-edit').classList.add('hidden');$('s-name').value='Auditoria recorrente';$('s-type').value='AUDIT';$('s-type').disabled=false;$('s-times').value='08:00,18:00';$('s-weekdays').value='1,2,3,4,5';$('s-monthdays').value='';$('s-lastday').checked=false;$('s-every').value='';$('s-start').value='00:00';$('s-end').value='23:59';$('s-overlap').value='SKIP';$('s-priority').value='100';$('s-attempts').value='3';$('s-urls').value='';$('s-query').value='';resetAuditPayload();typeFields()}
async function saveSchedule(){try{let id=$('s-id').value,body=scheduleBody();if(id){delete body.property_id;delete body.environment_id;delete body.job_type;await api(`/api/v1/schedules/${id}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify(body)});msg('Agendamento atualizado.')}else{await api(`/api/v1/projects/${$('project').value}/schedules`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});msg('Agendamento criado.')}resetForm();await loadSchedules()}catch(e){msg(e.message,true)}}function editSchedule(id){let x=state.schedules.find(s=>s.schedule_id===id);if(!x)return;$('s-id').value=id;$('form-title').textContent='Editar agendamento';$('save').textContent='Salvar alterações';$('cancel-edit').classList.remove('hidden');$('s-name').value=x.name;$('s-type').value=x.job_type;$('s-type').disabled=true;$('s-zone').value=x.timezone;$('s-overlap').value=x.overlap_policy;$('s-priority').value=x.priority;$('s-attempts').value=x.max_attempts;$('s-times').value=(x.recurrence.times||[]).join(',');$('s-weekdays').value=(x.recurrence.weekdays||[]).join(',');$('s-monthdays').value=(x.recurrence.month_days||[]).join(',');$('s-lastday').checked=!!x.recurrence.last_day;$('s-every').value=x.recurrence.every_minutes||'';$('s-start').value=x.recurrence.window_start;$('s-end').value=x.recurrence.window_end;$('s-urls').value=(x.urls||[]).join('\n');$('s-query').value=x.payload.query_id||'';$('s-audit-payload').value=JSON.stringify(x.payload||{},null,2);typeFields();window.scrollTo({top:0,behavior:'smooth'})}
async function action(id,a){try{await api(`/api/v1/schedules/${id}/${a}`,{method:'POST'});await loadSchedules()}catch(e){msg(e.message,true)}}async function disableSchedule(id){try{await api(`/api/v1/schedules/${id}`,{method:'DELETE'});await loadSchedules()}catch(e){msg(e.message,true)}}async function duplicateSchedule(id){let src=state.schedules.find(x=>x.schedule_id===id),name=prompt('Nome da cópia:',(src?.name||'Schedule')+' copy');if(!name)return;try{await api(`/api/v1/schedules/${id}/duplicate`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name})});await loadSchedules()}catch(e){msg(e.message,true)}}async function historySchedule(id){try{let [runs,events,next]=await Promise.all([api(`/api/v1/schedules/${id}/runs`),api(`/api/v1/schedules/${id}/events`),api(`/api/v1/schedules/${id}/next-occurrences?count=5`)]);$('schedule-detail').classList.remove('hidden');$('schedule-detail-body').innerHTML=`<h3>Próximas ocorrências</h3><p class="mono">${next.occurrences.map(esc).join('<br>')}</p><h3>Execuções</h3>${runs.length?`<table><tr><th>Quando</th><th>Occurrence</th><th>Job</th><th>Status</th><th>Resultado</th></tr>${runs.map(r=>`<tr><td>${esc(r.scheduled_for)}</td><td>${esc(r.occurrence_status)}</td><td class="mono">${esc(r.job_id)}</td><td>${esc(r.job_status)}</td><td>${esc(r.result_ref||r.reason||r.last_error||'—')}</td></tr>`).join('')}</table>`:'<p>Nenhuma execução.</p>'}<h3>Alterações administrativas</h3>${events.length?`<table><tr><th>Quando</th><th>Ação</th><th>Usuário</th><th>Detalhes</th></tr>${events.map(e=>`<tr><td>${esc(e.occurred_at)}</td><td>${esc(e.action)}</td><td>${esc(e.actor_user_id||'—')}</td><td class="mono">${esc(JSON.stringify(e.details||{}))}</td></tr>`).join('')}</table>`:'<p>Nenhum evento.</p>'}`;$('schedule-detail').scrollIntoView({behavior:'smooth'})}catch(e){msg(e.message,true)}}
async function loadSchedules(){if(!$('project').value)return;try{state.schedules=await api(`/api/v1/projects/${$('project').value}/schedules?limit=500`);let a=state.schedules;$('schedules').innerHTML=a.length?`<div class="table"><table><tr><th>Nome</th><th>Tipo</th><th>Status</th><th>Recorrência</th><th>Próxima</th><th>URLs</th><th>Falhas seq.</th><th>Ações</th></tr>${a.map(x=>`<tr><td>${esc(x.name)}<br><span class="mono">${esc(x.schedule_id)}</span></td><td>${esc(x.job_type)}</td><td><span class="tag">${esc(x.status)}</span></td><td class="mono">${esc(JSON.stringify(x.recurrence))}<br>${esc(x.timezone)} · ${esc(x.overlap_policy)}</td><td>${esc(x.next_run_at||'—')}</td><td>${esc(x.urls.length)}</td><td>${esc(x.consecutive_failures||0)}</td><td><div class="inline-actions"><button onclick="editSchedule('${x.schedule_id}')">Editar</button><button onclick="duplicateSchedule('${x.schedule_id}')">Duplicar</button><button onclick="historySchedule('${x.schedule_id}')">Histórico</button><button onclick="action('${x.schedule_id}','pause')">Pausar</button><button onclick="action('${x.schedule_id}','resume')">Ativar</button><button onclick="disableSchedule('${x.schedule_id}')">Desativar</button></div></td></tr>`).join('')}</table></div>`:'<p class="muted">Nenhum schedule.</p>'}catch(e){msg(e.message,true)}}
function periodFields(){document.querySelectorAll('.custom-range').forEach(x=>x.classList.toggle('hidden',$('u-period').value!=='CUSTOM'))}async function loadUsage(){let q=new URLSearchParams({group_by:$('u-group').value});q.set('workspace_id',$('ws').value);q.set('project_id',$('project').value);q.set('property_id',$('property').value);q.set('environment_id',$('environment').value);if($('u-period').value==='CUSTOM'){if($('u-start').value)q.set('start',$('u-start').value);if($('u-end').value)q.set('end',$('u-end').value)}else{q.set('period',$('u-period').value);q.set('timezone',$('u-zone').value)}[['domain','u-domain'],['url','u-url'],['user_id','u-user'],['job_type','u-job'],['provider','u-provider'],['integration','u-integration'],['operation','u-operation'],['event_status','u-status'],['model','u-model'],['resource_type','u-resource']].forEach(([k,id])=>{if($(id).value)q.set(k,$(id).value)});try{let d=await api(`/api/v1/organizations/${$('org').value}/consumption?${q}`),s=d.summary;let cost=Object.keys(s.cost_by_currency).length?JSON.stringify(s.cost_by_currency):'não disponível';$('usage-metrics').innerHTML=`<div class="metric">Eventos<b>${s.event_count}</b></div><div class="metric">Falhas<b>${s.failure_count}</b></div><div class="metric">Retries / fallback<b>${s.retry_count} / ${s.fallback_count}</b></div><div class="metric">Tokens<b>${s.total_tokens}</b></div><div class="metric">Custo<b style="font-size:1rem">${esc(cost)}</b></div>`;$('usage-coverage').textContent=`Cobertura dimensional: URL ${d.coverage.with_url}/${d.coverage.events}; usuário ${d.coverage.with_user}/${d.coverage.events}; provider ${d.coverage.with_provider}/${d.coverage.events}; custo conhecido ${d.coverage.with_cost}/${d.coverage.events}. Ausência não é convertida em zero.`;$('usage-table').innerHTML=d.groups.length?`<div class="table"><table><tr><th>Dimensões</th><th>Quantidade</th><th>Custo</th><th>Tokens in/out/reasoning</th><th>Duração</th><th>Falhas</th></tr>${d.groups.map(x=>`<tr><td class="mono">${esc(JSON.stringify(x.dimensions))}</td><td>${esc(JSON.stringify(x.quantity_by_unit))}</td><td>${esc(JSON.stringify(x.cost_by_currency))}${x.cost_unknown_events?' · '+x.cost_unknown_events+' eventos sem custo conhecido':''}</td><td>${x.input_tokens}/${x.output_tokens}/${x.reasoning_tokens}</td><td>${x.duration_ms} ms</td><td>${x.failure_count}</td></tr>`).join('')}</table></div>`:'<p class="muted">Nenhum evento no filtro.</p>'}catch(e){msg(e.message,true)}}
document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tabs button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.panel').forEach(x=>x.classList.toggle('active',x.id===b.dataset.tab))});document.querySelectorAll('[data-shift]').forEach(b=>b.onclick=()=>{let [a,z]=b.dataset.shift.split(',');$('s-start').value=a;$('s-end').value=z;if(!$('s-every').value)$('s-every').value=60});$('org').onchange=async()=>{state.ws=await api(`/api/v1/organizations/${$('org').value}/workspaces`);await chooseWorkspace()};$('ws').onchange=async()=>{state.projects=await api(`/api/v1/workspaces/${$('ws').value}/projects`);await chooseProject()};$('project').onchange=chooseProject;$('property').onchange=chooseProperty;$('s-type').onchange=typeFields;$('save').onclick=saveSchedule;$('cancel-edit').onclick=resetForm;$('reload').onclick=loadSchedules;$('reset-audit').onclick=resetAuditPayload;$('u-period').onchange=periodFields;$('usage-load').onclick=loadUsage;typeFields();periodFields();boot();
</script></body></html>'''
